create or replace function public.new_signup_code() returns text language sql volatile as $$ select 'NEW5-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)); $$;
create or replace function public.customer_credit_cents(p_store uuid, p_points int) returns int language sql stable security definer set search_path = public as $$ select greatest(coalesce(p_points, 0), 0) * greatest(public.store_setting_int(p_store, 'rewards_point_value_cents', 1), 0); $$;
create or replace function public.customer_card(p_store uuid, r public.customers) returns jsonb language plpgsql stable security definer set search_path = public as $$ declare v_bal int; begin v_bal := public.customer_points_balance_internal(p_store, r.id); return jsonb_build_object('id', r.id, 'store_id', r.store_id, 'phone', r.phone, 'name', r.name, 'email', r.email, 'marketing_opt_in', r.marketing_opt_in, 'first_purchase_discount_used', r.first_purchase_discount_used, 'created_at', r.created_at, 'signup_code', r.signup_code, 'balance', v_bal, 'credit_cents', public.customer_credit_cents(p_store, v_bal)); end; $$;
create or replace function public.lookup_customer_by_phone(p_phone text) returns jsonb language plpgsql stable security definer set search_path = public as $$ declare v_store uuid := public.current_store_id(); v_phone text; r public.customers; begin perform public.assert_staff_or_service(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; v_phone := public.normalize_phone(p_phone); if v_phone is null then raise exception 'invalid_phone' using errcode = '22023'; end if; select * into r from public.customers where store_id = v_store and phone = v_phone; if not found then return null; end if; return public.customer_card(v_store, r); end; $$;
create or replace function public.upsert_customer(p_phone text, p_name text default null, p_email text default null, p_marketing_opt_in boolean default false) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_store uuid := public.current_store_id(); v_phone text; r public.customers; begin perform public.assert_staff_or_service(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; v_phone := public.normalize_phone(p_phone); if v_phone is null then raise exception 'invalid_phone' using errcode = '22023'; end if; insert into public.customers (store_id, phone, name, email, marketing_opt_in, signup_code) values (v_store, v_phone, nullif(btrim(coalesce(p_name, '')), ''), nullif(btrim(coalesce(p_email, '')), ''), coalesce(p_marketing_opt_in, false), public.new_signup_code()) on conflict (store_id, phone) do update set name = coalesce(excluded.name, public.customers.name), email = coalesce(excluded.email, public.customers.email), marketing_opt_in = public.customers.marketing_opt_in or excluded.marketing_opt_in returning * into r; return public.customer_card(v_store, r); end; $$;;
